add_filter( 'woocommerce_product_related_posts_shuffle', 'perfectpixel_related_no_shuffle' );
add_filter( 'woocommerce_output_related_products_args', 'perfectpixel_related_order_args', 20 );

function perfectpixel_related_no_shuffle() {
	return false;
}

function perfectpixel_related_order_args( $args ) {
	$orderby = sanitize_key( '{{related_orderby}}' );
	if ( in_array( $orderby, array( 'date', 'title', 'price', 'popularity', 'rating', 'id', 'menu_order' ), true ) ) {
		$args['orderby'] = $orderby;
		$args['order']   = 'asc' === strtolower( '{{related_order}}' ) ? 'asc' : 'desc';
	}
	return $args;
}
